# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 4: ON THE PHONE — FORMAL VS. INFORMAL PHONE CALLS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Formal Phone Language (Resmî Dil)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Good morning, this is ... calling.</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">• May / Could I speak to Mr. Smith, please?</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">• Could you put me through to the manager?</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#1e3a8a">• Can you hold on a moment, please?</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#1e3a8a">• I am afraid he is not available right now.</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#1e3a8a">• Would you like to leave a message?</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• Could you spell your name, please?</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Informal Phone Language (Samimi Dil)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Hi! It is (It\'s) Jack. Is Tom in / there?</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#14532d">• Hang on a minute; I\'ll get him.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#14532d">• He has gone out. Tell him to call me back.</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#14532d">• What\'s up? Let\'s meet at the café.</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#14532d">• I\'ll talk to you soon. / See you later!</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#14532d">• Sorry, I can\'t hear you well. It\'s a bad line.</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Keep in touch! Bye for now.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SMARTPHONE PURPOSES, REASONS &amp; PROS AND CONS</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">1. Purposes (Amaçlar: to + V1)</text>\n  <text x="125" y="94" text-anchor="middle" font-size="10" fill="#713f12">• to keep in touch with friends</text>\n  <text x="125" y="114" text-anchor="middle" font-size="10" fill="#713f12">• to do online shopping / pay bills</text>\n  <text x="125" y="134" text-anchor="middle" font-size="10" fill="#713f12">• to practice foreign languages</text>\n  <text x="125" y="154" text-anchor="middle" font-size="10" fill="#713f12">• to find our way in traffic</text>\n  <text x="125" y="174" text-anchor="middle" font-size="10" fill="#713f12">• to search for information</text>\n  <text x="125" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">• to book a flight ticket / hotel</text>\n  <text x="125" y="218" text-anchor="middle" font-size="10" fill="#713f12">• to share photos and videos</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Pros (Advantages)</text>\n  <text x="350" y="94" text-anchor="middle" font-size="10" fill="#164e63">• Easy and fast communication</text>\n  <text x="350" y="114" text-anchor="middle" font-size="10" fill="#164e63">• Carry easily in our pockets</text>\n  <text x="350" y="134" text-anchor="middle" font-size="10" fill="#164e63">• Useful educational applications</text>\n  <text x="350" y="154" text-anchor="middle" font-size="10" fill="#164e63">• Quick access to rescue in</text>\n  <text x="350" y="170" text-anchor="middle" font-size="10" fill="#164e63">emergency situations</text>\n  <text x="350" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#0e7490">Reason: because it is fast,</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10" font-weight="bold" fill="#0e7490">cheap and practical.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">3. Cons (Disadvantages)</text>\n  <text x="575" y="94" text-anchor="middle" font-size="10" fill="#881337">• Screen addiction (Bağımlılık)</text>\n  <text x="575" y="114" text-anchor="middle" font-size="10" fill="#881337">• Less face-to-face interaction</text>\n  <text x="575" y="134" text-anchor="middle" font-size="10" fill="#881337">• Security risks / personal data</text>\n  <text x="575" y="154" text-anchor="middle" font-size="10" fill="#881337">• Eye ve neck health problems</text>\n  <text x="575" y="174" text-anchor="middle" font-size="10" fill="#881337">• Disturbing concentration</text>\n  <text x="575" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">Spontaneous Decision (will):</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10" fill="#881337">"I\'ll switch off my phone now."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CALL CENTER DIALOGUES &amp; UNIT 4 KEY VOCABULARY</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Call Center &amp; Customer Service</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#581c87">• Agent: How can I help you today?</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#581c87">• Customer: I want to make a complaint.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#581c87">• I\'d like to return a broken / damaged product.</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#581c87">• I want to book / change a flight ticket.</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#581c87">• I want to report a delivery problem.</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#581c87">• Agent: I\'ll connect you to customer service.</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• For English, please press nine / dial extension 105.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f1f5f9" stroke="#64748b" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#334155">Essential Phone Vocabulary</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#1e293b">• pick up = answer the phone (telefonu açmak)</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#1e293b">• hang up = end a phone call (telefonu kapatmak)</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#1e293b">• hold on / hang on = wait on the line (beklemek)</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#1e293b">• put through = connect someone (bağlamak)</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#1e293b">• engaged = busy / in use (hat meşgul)</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#1e293b">• available = free / not busy (müsait / uygun)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">• memo = short note · extension = dahili numara</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
